<script setup>
import {ref,shallowRef,computed,watch,onBeforeUnmount} from 'vue';
import {call} from '../api';
import {titleSnapshot,prepareTitle,loadTitleFont,drawTitle} from '../title-render.mjs';
import {templateTitlePointerOffset,templateTitleLayout} from '../../server/title-layout.mjs';
import {titleTemplates} from '../../server/title-model.mjs';
import {customTitleLayout,customTitlePointerTop} from '../title-custom-preview.mjs';
const props=defineProps({edit:Object,width:{type:Number,default:1080},height:{type:Number,default:1920},fonts:Array,thumbnail:Boolean,interactive:Boolean});
const emit=defineEmits(['move','error']);const canvas=ref(),error=ref(''),bounds=ref(null),prepared=shallowRef(null),viewSize=ref({width:0,height:0});let serial=0,drag=null,observer;
const domTemplate=computed(()=>props.interactive&&prepared.value?.design.mode==='template');
const previewLayout=computed(()=>domTemplate.value?templateTitleLayout({...prepared.value,width:viewSize.value.width||props.width,height:viewSize.value.height||props.height}):null);
const customLayout=computed(()=>props.interactive&&prepared.value?.design.mode==='custom'?customTitleLayout(prepared.value,{width:viewSize.value.width||props.width,height:viewSize.value.height||props.height}):null);
const pixel=value=>Number(value.toFixed(2))+'px';
function lineStyle(line){const s=prepared.value.style,scale=(viewSize.value.height||props.height)/1080;return {left:pixel(line.x),top:pixel(line.y),width:pixel(line.boxWidth),maxWidth:pixel(line.boxWidth),fontFamily:`"${s.renderFamily||s.fontFamily}", Microsoft YaHei, sans-serif`,fontSize:pixel(line.fontSize),fontWeight:line.fontWeight,fontStyle:line.italic?'italic':'normal',color:line.color,WebkitTextStroke:s.stroke.enabled&&s.stroke.width?`${pixel(Math.max(1,s.stroke.width*scale))} ${s.stroke.color}`:'0 transparent',textShadow:s.shadow.enabled?`${pixel(Math.max(1,(s.shadow.distance||3)*scale))} ${pixel(Math.max(1,(s.shadow.distance||3)*scale))} 0 ${s.shadow.color}`:'none'};}
async function paint(){const version=++serial;try{const snapshot=titleSnapshot(props.edit,props.width,props.height),fonts=props.fonts||await call('listSubtitleFonts'),ready=await prepareTitle(snapshot,fonts,f=>loadTitleFont(call,f));if(version!==serial||!canvas.value)return;bounds.value=ready.design.mode==='template'?drawTitle(canvas.value,ready):{layout:{kind:'reference-custom-dom'},offsetY:ready.design.offsetY};prepared.value=ready;error.value='';emit('error','');}catch(e){if(version!==serial)return;bounds.value=null;prepared.value=null;canvas.value?.getContext('2d').clearRect(0,0,props.width,props.height);error.value=e.message.replace(/封面/g,'标题');emit('error',error.value);}}
// 按实际CSS媒体框缩放DOM文字，最小字号和描边不受原生视频分辨率影响。
watch(canvas,element=>{observer?.disconnect();if(!element)return;observer=new ResizeObserver(()=>{const r=element.getBoundingClientRect();viewSize.value={width:r.width,height:r.height};});observer.observe(element);},{flush:'post'});
watch(()=>[canvas.value,props.edit,props.width,props.height,props.fonts],paint,{deep:true,flush:'post'});watch(()=>props.interactive,()=>drag=null);onBeforeUnmount(()=>{serial++;drag=null;observer?.disconnect();});
// 从实际可见坐标开始移动，避免历史偏移越过画面时拖动或方向键失去响应。
function templatePosition(event){const preset=titleTemplates.find(t=>t.id===props.edit.titleDesign?.templateId),offsetY=templateTitlePointerOffset(event.clientY,canvas.value.getBoundingClientRect(),Number(preset?.style.offsetY));if(offsetY!==null)emit('move',{offsetY});}
function customPosition(event){const top=customTitlePointerTop(event.clientY,canvas.value.getBoundingClientRect(),props.height);if(top!==null)emit('move',{offsetY:0,custom:{...props.edit.titleDesign.custom,top}});}
function down(event){if(!props.interactive||!bounds.value||event.button!==0)return;drag={template:bounds.value.layout?.kind==='reference-template'};event.currentTarget.setPointerCapture(event.pointerId);event.preventDefault();if(drag.template)templatePosition(event);else customPosition(event);}
function move(event){if(!drag||!props.interactive)return;if(drag.template)templatePosition(event);else customPosition(event);}
function up(event){drag=null;if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);}
function key(event){const step={ArrowUp:-10,ArrowDown:10}[event.key];if(!step||!props.interactive||!bounds.value)return;event.preventDefault();if(customLayout.value){const s=props.edit.titleDesign.custom;emit('move',{offsetY:0,custom:{...s,top:Math.max(0,Math.min(10000,Math.round(s.top+props.edit.titleDesign.offsetY+step)))}});}else emit('move',{offsetY:Math.max(-10000,Math.min(10000,Math.round(bounds.value.offsetY+step)))});}
</script>
<template><div class="title-canvas-wrap" :class="{thumbnail,interactive}"><canvas ref="canvas" :width="width" :height="height" aria-label="标题图层" :style="domTemplate||customLayout?{opacity:0}:undefined"/><div v-if="previewLayout" class="title-template-overlay" aria-label="模板标题预览"><div v-if="previewLayout.mask" class="title-template-mask" :style="{top:pixel(previewLayout.mask.y),height:pixel(previewLayout.mask.height),background:previewLayout.mask.color}"/><div v-for="line in previewLayout.lines" :key="line.key" class="title-template-line" :style="lineStyle(line)">{{line.text}}</div></div><div v-if="customLayout" class="title-custom-overlay" :style="customLayout.style" role="button" tabindex="0" aria-label="移动自定义标题，方向键微调" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @lostpointercapture="drag=null" @keydown="key"><span v-for="(text,index) in customLayout.lines" :key="index" :style="customLayout.lineStyle">{{text}}</span></div><div v-if="interactive&&bounds&&domTemplate" class="title-drag-handle" role="button" tabindex="0" aria-label="移动标题，方向键微调" :style="{left:bounds.x/1080*100+'%',top:bounds.y/(height/width*1080)*100+'%',width:bounds.width/1080*100+'%',height:bounds.height/(height/width*1080)*100+'%'}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @lostpointercapture="drag=null" @keydown="key"/><span v-if="error" class="title-font-error" :title="error">{{thumbnail?'字体未就绪':error}}</span></div></template>
